contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 _value) public payable {
        uint256 beforeTotalDistributed = c.totalDistributed(); if (__ESBMC_reverted()) return;
        require(_value <= beforeTotalDistributed);
        c.burn(_value); if (__ESBMC_reverted()) return;
        uint256 afterTotalDistributed = c.totalDistributed(); if (__ESBMC_reverted()) return;
        assert(afterTotalDistributed + _value == beforeTotalDistributed);
    }

    receive() external payable {}
}

