pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    XBORNID c;

    function setUp() public {
        c = new XBORNID();
    }

    function _run(uint256 _value) internal {
        uint256 beforeTotalDistributed;
        try c.totalDistributed() returns (uint256 __r) { beforeTotalDistributed = __r; } catch { return; }
        vm.assume(_value <= beforeTotalDistributed);
        try c.burn(_value) {} catch { return; }
        uint256 afterTotalDistributed;
        try c.totalDistributed() returns (uint256 __r) { afterTotalDistributed = __r; } catch { return; }
        assertTrue(afterTotalDistributed + _value == beforeTotalDistributed);
    }

    function testFuzz_run(uint256 _value) public {
        _run(_value);
    }

    receive() external payable {}
}
